Map<String, List<String>> calls = Map.of(
    "gateway", List.of("order", "user"),
    "order", List.of("payment", "inventory"),
    "user", List.of("payment"),
    "payment", List.of("ledger"),
    "inventory", List.of(),
    "ledger", List.of());
Map<String, Integer> hops = new LinkedHashMap<>();
Deque<String> queue = new ArrayDeque<>();
hops.put("gateway", 0);
queue.add("gateway");
while (!queue.isEmpty()) {
    String service = queue.poll();
    for (String next : calls.get(service)) {
        if (!hops.containsKey(next)) {
            hops.put(next, hops.get(service) + 1);
            queue.add(next);
        }
    }
}
System.out.println(hops);
